mapper.select:
SELECT id, name, price, duration_minutes, description, active, created_at
FROM service_item
WHERE id = #{id}

mapper.update:
UPDATE service_item
SET active = 0
WHERE id = #{id}

mapper.select:
SELECT id, service_item_id, image_url, display_order FROM service_item_image WHERE service_item_id IN
#{serviceItemId}
ORDER BY service_item_id, display_order
